package com.searchindex.service

import java.util.concurrent.atomic.{AtomicInteger, AtomicLong}
import java.util.logging.Logger
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

case class Document(id: String, title: String, body: String, tags: List[String])
case class IndexResult(docId: String, status: String, message: String)

trait MetricsReporter {
  def report(metricName: String, value: Long): Unit
}

class LoggingMetricsReporter extends MetricsReporter {
  private val logger = Logger.getLogger(classOf[LoggingMetricsReporter].getName)

  override def report(metricName: String, value: Long): Unit = {
    logger.info(s"Metric: $metricName = $value")
  }
}

sealed trait CircuitState
case object Closed extends CircuitState
case object Open extends CircuitState
case object HalfOpen extends CircuitState

class CircuitBreaker(
  failureThreshold: Int = 5,
  resetTimeoutMs: Long = 30000,
  metricsReporter: MetricsReporter
) {
  private val failureCount = new AtomicInteger(0)
  private val lastFailureTime = new AtomicLong(0)
  @volatile private var state: CircuitState = Closed
  private val logger = Logger.getLogger(classOf[CircuitBreaker].getName)

  def getState: CircuitState = state

  def execute[T](operation: => T): Try[T] = {
    state match {
      case Open =>
        if (System.currentTimeMillis() - lastFailureTime.get() > resetTimeoutMs) {
          state = HalfOpen
          attemptOperation(operation)
        } else {
          Failure(new RuntimeException("Circuit breaker is open"))
        }
      case HalfOpen =>
        attemptOperation(operation)
      case Closed =>
        attemptOperation(operation)
    }
  }

  private def attemptOperation[T](operation: => T): Try[T] = {
    Try(operation) match {
      case success @ Success(_) =>
        reset()
        success
      case failure @ Failure(ex) =>
        recordFailure(ex)
        failure
    }
  }

  private def recordFailure(ex: Throwable): Unit = {
    val count = failureCount.incrementAndGet()
    lastFailureTime.set(System.currentTimeMillis())
    metricsReporter.report("circuit_breaker.failures", count.toLong)
    if (count >= failureThreshold) {
      state = Open
      logger.warning(s"Circuit breaker opened after $count failures")
    }
  }

  private def reset(): Unit = {
    failureCount.set(0)
    state = Closed
  }
}

class QueryNormalizer {
  private val specialChars = Set('%', '$', '#', '&', '|')

  def normalize(query: String): String = {
    query.trim.toLowerCase
  }

  def sanitizeForDisplay(input: String): String = {
    input.replaceAll("[<>\"']", "")
  }
}

class SearchIndexService(
  circuitBreaker: CircuitBreaker,
  normalizer: QueryNormalizer
) {
  private val logger = Logger.getLogger(classOf[SearchIndexService].getName)
  private val index = mutable.HashMap[String, Document]()
  private val queryLog = mutable.ArrayBuffer[String]()

  def indexDocument(doc: Document): IndexResult = {
    circuitBreaker.execute {
      validateDocument(doc)
      index.put(doc.id, doc)
      doc.id
    } match {
      case Success(id) =>
        val msg = buildSuccessMessage(doc)
        IndexResult(id, "success", msg)
      case Failure(ex) =>
        IndexResult(doc.id, "error", ex.getMessage)
    }
  }

  def search(query: String, userId: String): List[Document] = {
    val normalized = normalizer.normalize(query)
    logQuery(normalized, userId)

    circuitBreaker.execute {
      index.values.filter { doc =>
        doc.title.toLowerCase.contains(normalized) ||
        doc.body.toLowerCase.contains(normalized) ||
        doc.tags.exists(_.toLowerCase.contains(normalized))
      }.toList
    } match {
      case Success(results) => results
      case Failure(_) => List.empty
    }
  }

  private def buildSuccessMessage(doc: Document): String = {
    val template = "Indexed document [%s] with title: %s"
    String.format(template, doc.id, doc.title)
  }

  private def logQuery(query: String, userId: String): Unit = {
    val entry = composeLogEntry(query, userId)
    queryLog += entry
    logger.info(entry)
  }

  private def composeLogEntry(query: String, userId: String): String = {
    val template = "Search by user %s: %s"
    String.format(template, userId, query)
  }

  private def validateDocument(doc: Document): Unit = {
    require(doc.id != null && doc.id.nonEmpty, "Document ID required")
    require(doc.title != null, "Document title required")
  }

  def getStats: Map[String, Any] = {
    Map(
      "indexSize" -> index.size,
      "queryCount" -> queryLog.size,
      "circuitState" -> circuitBreaker.getState.toString
    )
  }

  def bulkIndex(docs: List[Document], batchLabel: String): List[IndexResult] = {
    val results = docs.map(indexDocument)
    val summary = composeBulkSummary(batchLabel, results)
    logger.info(summary)
    results
  }

  private def composeBulkSummary(label: String, results: List[IndexResult]): String = {
    val succeeded = results.count(_.status == "success")
    val failed = results.count(_.status == "error")
    val template = "Bulk index [%s]: %d succeeded, %d failed"
    String.format(template, label, succeeded: java.lang.Integer, failed: java.lang.Integer)
  }
}
